SELECT 'appointments.patient_id -> patients.patient_id' relationship, COUNT(*) orphan_rows FROM healthcare_silver.appointments a LEFT ANTI JOIN healthcare_silver.patients p ON a.patient_id=p.patient_id UNION ALL SELECT 'appointments.doctor_id -> doctors.doctor_id', COUNT(*) FROM healthcare_silver.appointments a LEFT ANTI JOIN healthcare_silver.doctors d ON a.doctor_id=d.doctor_id UNION ALL SELECT 'billing.patient_id -> patients.patient_id', COUNT(*) FROM healthcare_silver.billing b LEFT ANTI JOIN healthcare_silver.patients p ON b.patient_id=p.patient_id UNION ALL SELECT 'billing.treatment_id -> treatments.treatment_id', COUNT(*) FROM healthcare_silver.billing b LEFT ANTI JOIN healthcare_silver.treatments t ON b.treatment_id=t.treatment_id UNION ALL SELECT 'treatments.appointment_id -> appointments.appointment_id', COUNT(*) FROM healthcare_silver.treatments t LEFT ANTI JOIN healthcare_silver.appointments a ON t.appointment_id=a.appointment_id;